insert into public.foods_catalog
  (food_code, name_th, name_en, energy_kcal_per_100g, protein_g_per_100g,
   fat_g_per_100g, carbs_g_per_100g, fiber_g_per_100g, calcium_mg_per_100g,
   sodium_mg_per_100g, serving_basis_grams, is_usable, has_sugar_data,
   has_sodium_data, data_quality, source_name, source_url, verified,
   common_name_th, search_aliases)
select f.food_code, f.name_th, f.name_en, f.kcal, f.protein, f.fat, f.carbs,
       f.fiber, f.calcium, f.sodium, 100, true, false, f.sodium is not null,
       'partial', 'ตารางแสดงคุณค่าทางโภชนาการของอาหารไทย 2561, สำนักโภชนาการ กรมอนามัย', 'https://nutrition2.anamai.moph.go.th/th/thai-food-composition-table', false, f.common_name_th, f.search_aliases
from foods f
where not exists (
  select 1 from public.foods_catalog c where c.food_code = f.food_code
);

