insert into public.food_servings
  (food_id, label, grams, is_default, is_estimate, verified, source_name, source_url)
select c.id, s.label, s.grams, true, s.is_estimate, true, s.source_name, s.source_url
from servings s
join public.foods_catalog c on c.food_code = s.food_code
where not exists (
  select 1 from public.food_servings fs
  where fs.food_id = c.id and fs.label = s.label
);

-- Check.
select count(*) as doh_foods from public.foods_catalog where food_code like 'DOH%';
select c.food_code, c.name_th, fs.label, fs.grams, fs.is_estimate
from public.food_servings fs
join public.foods_catalog c on c.id = fs.food_id
where fs.source_url in ('https://nutrition2.anamai.moph.go.th/th/thai-food-composition-table', 'https://doi.org/10.3390/ijerph20053992')
order by c.food_code;
